package com.gestordevendas.api.food;
import com.gestordevendas.api.company.Company; import com.gestordevendas.api.product.Product; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="snack_recipe_items") public class SnackRecipeItem { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="company_id") private Company company; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="snack_id") private Snack snack; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id") private Product product; @Column(nullable=false) private BigDecimal quantity; protected SnackRecipeItem(){} public static SnackRecipeItem create(Company c,Snack s,Product p,BigDecimal q){var x=new SnackRecipeItem();x.id=UUID.randomUUID();x.company=c;x.snack=s;x.product=p;x.quantity=q;return x;} public UUID getId(){return id;} public Product getProduct(){return product;} public BigDecimal getQuantity(){return quantity;} }
